<div x-data="{ barangayData: [{ name: 'Poblacion', count: 2 }, { name: 'Cay Pombo', count: 2 }, { name: 'Tumana', count: 2 }, { name: 'Bagbaguin', count: 1 }, { name: 'Balasing', count: 1 }, { name: 'Guyong', count: 1 }, { name: 'Longos', count: 1 }], get maxBarangay() { return Math.max(...this.barangayData.map(i => i.count), 1); }, ageData: [{ range: '60–69', count: 1, color: '#3B82F6', dot: 'bg-blue-500' }, { range: '70–79', count: 3, color: '#8B5CF6', dot: 'bg-purple-500' }, { range: '80–89', count: 4, color: '#F59E0B', dot: 'bg-amber-500' }, { range: '90+', count: 2, color: '#EF4444', dot: 'bg-red-500' }], get totalAge() { return this.ageData.reduce((sum, item) => sum + item.count, 0); }, genderData: [{ label: 'Female', count: 5, color: '#EC4899', dot: 'bg-pink-500' }, { label: 'Male', count: 5, color: '#3B82F6', dot: 'bg-blue-500' }], get totalGender() { return this.genderData.reduce((sum, item) => sum + item.count, 0); }, segmentOffset(data, index) { return -(data.slice(0, index).reduce((sum, item) => sum + item.count, 0) / data.reduce((sum, item) => sum + item.count, 0) * 100); } }" class="min-h-[calc(100vh-65px)] bg-slate-50 px-6 pb-8 pt-8 dark:bg-slate-950">
    <section class="mb-6 grid grid-cols-1 gap-5 md:grid-cols-3">
        <article class="flex items-start justify-between rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div><h3 class="text-sm font-semibold text-gray-900 dark:text-white">Total Active Seniors</h3><div class="my-2 text-4xl font-bold text-gray-900 dark:text-white">1,248</div><p class="text-xs text-gray-500">Across 24 barangays</p></div><div class="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="9" cy="8" r="3"/><circle cx="16" cy="9" r="2.5"/><path stroke-linecap="round" d="M3 20a6 6 0 0 1 12 0m1-5a5 5 0 0 1 6 5"/></svg></div></article>
        <article class="flex items-start justify-between rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div><h3 class="text-sm font-semibold text-gray-900 dark:text-white">IDs Ready for Release</h3><div class="my-2 text-4xl font-bold text-gray-900 dark:text-white">14</div><p class="text-xs text-gray-500">Awaiting front desk pickup</p></div><div class="flex h-10 w-10 items-center justify-center rounded-xl bg-green-50 text-green-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="12" r="2"/><path stroke-linecap="round" d="M14 10h4m-4 4h3"/></svg></div></article>
        <article class="flex items-start justify-between rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div><h3 class="text-sm font-semibold text-gray-900 dark:text-white">Upcoming Milestones</h3><div class="my-2 text-4xl font-bold text-gray-900 dark:text-white">8</div><p class="text-xs text-gray-500">Turning 80, 90, or 100+ this month</p></div><div class="flex h-10 w-10 items-center justify-center rounded-xl bg-purple-50 text-purple-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" d="M20 12v8H4v-8M2 8h20v4H2zM12 8v12M12 8H8.5a2.5 2.5 0 1 1 0-5C11 3 12 8 12 8Zm0 0h3.5a2.5 2.5 0 1 0 0-5C13 3 12 8 12 8Z"/></svg></div></article>
    </section>

    <section class="mb-6 rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="flex items-start justify-between"><div><p class="text-xs font-semibold uppercase tracking-wider text-gray-500">Population by Barangay</p><p class="mt-1 text-sm text-gray-500">Top 8 barangays by senior citizen count</p><p class="mt-2 max-w-2xl text-xs text-gray-400">Used to plan mobile registration drives and barangay-level payout distribution.</p></div><div class="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 text-blue-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M4 19V5m0 14h17M8 16v-3m4 3V8m4 8v-6m4 6V4"/></svg></div></div><div class="mt-4 grid h-56 grid-cols-7 items-end gap-4 border-b border-gray-100 pt-8 dark:border-slate-800"><template x-for="item in barangayData" :key="item.name"><div class="flex h-full flex-col items-center justify-end"><div class="relative flex w-full flex-1 items-end"><span class="absolute -top-5 w-full text-center text-xs text-gray-500" x-text="item.count"></span><div class="w-full rounded-t-md bg-blue-500 transition-all duration-300 hover:bg-blue-600" :style="'height: ' + ((item.count / maxBarangay) * 100) + '%'" :title="item.name"></div></div><span class="mt-2 w-full truncate text-center text-[10px] text-gray-400" x-text="item.name"></span></div></template></div></section>

    <section class="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <article class="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="flex items-start justify-between"><div><p class="text-xs font-semibold uppercase tracking-wider text-gray-500">Age Bracket Distribution</p><p class="mt-1 text-sm text-gray-500">All 10 registered seniors</p><p class="mt-2 text-xs text-gray-400">Forecasts upcoming milestone cash gift budgets by age tier.</p></div><div class="flex h-9 w-9 items-center justify-center rounded-xl bg-purple-50 text-purple-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" d="M12 3a9 9 0 1 0 9 9"/><path stroke-linecap="round" d="M12 3v9h9"/><path stroke-linecap="round" d="M12 7a5 5 0 1 0 5 5"/></svg></div></div><div class="mt-6 flex items-center justify-between gap-8"><div class="relative h-36 w-36 shrink-0"><svg class="h-full w-full -rotate-90" viewBox="0 0 100 100" aria-label="Age bracket distribution"><circle cx="50" cy="50" r="40" pathLength="100" fill="none" stroke="#f1f5f9" stroke-width="18"/><template x-for="(item, index) in ageData" :key="item.range"><circle cx="50" cy="50" r="40" pathLength="100" fill="none" :stroke="item.color" stroke-width="18" :stroke-dasharray="`${(item.count / totalAge) * 100} ${100 - (item.count / totalAge) * 100}`" :stroke-dashoffset="segmentOffset(ageData, index)"/></template></svg><div class="absolute inset-0 flex items-center justify-center text-xl font-bold text-slate-900 dark:text-white" x-text="totalAge"></div></div><div class="flex-1 space-y-3"> <template x-for="item in ageData" :key="item.range"><div class="flex items-center justify-between gap-4 text-sm"><span class="flex items-center gap-2 text-gray-500"><span class="h-2.5 w-2.5 rounded-full" :class="item.dot"></span><span x-text="item.range"></span></span><b class="text-gray-900 dark:text-white" x-text="item.count"></b></div></template></div></div></article>
        <article class="flex flex-col justify-between rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div><div class="flex items-start justify-between"><div><p class="text-xs font-semibold uppercase tracking-wider text-gray-500">Gender &amp; Status</p><p class="mt-1 text-sm text-gray-500">Demographic breakdown</p><p class="mt-2 text-xs text-gray-400">Monitors gender ratio and registry health for official LGU reporting.</p></div><div class="flex h-9 w-9 items-center justify-center rounded-xl bg-pink-50 text-pink-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="9" cy="8" r="3"/><circle cx="16" cy="9" r="2.5"/><path stroke-linecap="round" d="M3 20a6 6 0 0 1 12 0m1-5a5 5 0 0 1 6 5"/></svg></div></div><div class="my-6 flex items-center justify-between gap-8"><div class="relative h-36 w-36 shrink-0"><svg class="h-full w-full -rotate-90" viewBox="0 0 100 100" aria-label="Gender distribution"><circle cx="50" cy="50" r="40" pathLength="100" fill="none" stroke="#f1f5f9" stroke-width="18"/><template x-for="(item, index) in genderData" :key="item.label"><circle cx="50" cy="50" r="40" pathLength="100" fill="none" :stroke="item.color" stroke-width="18" :stroke-dasharray="`${(item.count / totalGender) * 100} ${100 - (item.count / totalGender) * 100}`" :stroke-dashoffset="segmentOffset(genderData, index)"/></template></svg><div class="absolute inset-0 flex items-center justify-center text-xl font-bold text-slate-900 dark:text-white" x-text="totalGender"></div></div><div class="flex-1 space-y-3"><template x-for="item in genderData" :key="item.label"><div class="flex items-center justify-between gap-4 text-sm"><span class="flex items-center gap-2 text-gray-500"><span class="h-2.5 w-2.5 rounded-full" :class="item.dot"></span><span x-text="item.label"></span></span><b class="text-gray-900 dark:text-white" x-text="item.count"></b></div></template></div></div></div><div class="grid grid-cols-3 border-t border-gray-100 pt-4 text-center dark:border-slate-800"><div><div class="text-xl font-bold text-green-600">8</div><div class="mt-0.5 text-xs text-gray-500">Active</div></div><div><div class="text-xl font-bold text-gray-600">1</div><div class="mt-0.5 text-xs text-gray-500">Deceased</div></div><div><div class="text-xl font-bold text-gray-700">3</div><div class="mt-0.5 text-xs text-gray-500">Other</div></div></div></article>
